//! Shared state for DockDemo — generated by mobius_codegen.
//!
//! Each interface is a Path A boundary: one `Dynamic<T>` cell per
//! state field. Citizens hold `&Iface` and read / write the cells;
//! nothing here is passed `&mut`.

use egui_mobius_reactive::Dynamic;
use egui_lens::{LogColors, ReactiveEventLoggerState};

/// `enum Theme` from the `.mobius` source.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Theme {
    CopperDark,
    TokyoNight,
    Light,
}

impl Theme {
    pub const ALL: [Theme; 3] = [Theme::CopperDark, Theme::TokyoNight, Theme::Light];

    pub fn label(self) -> &'static str {
        match self {
            Theme::CopperDark => "CopperDark",
            Theme::TokyoNight => "TokyoNight",
            Theme::Light => "Light",
        }
    }
}

/// Path A cells of the `Chrome` interface.
#[derive(Clone)]
pub struct Chrome {
    pub theme: Dynamic<Theme>,
    pub show_about: Dynamic<bool>,
    pub clock: Dynamic<String>,
}

impl Chrome {
    pub fn new() -> Self {
        Self {
            theme: Dynamic::new(Theme::CopperDark),
            show_about: Dynamic::new(false),
            clock: Dynamic::new(String::new()),
        }
    }
}

/// Path A cells of the `Channel` interface.
#[derive(Clone)]
pub struct Channel {
    pub level: Dynamic<f32>,
}

impl Channel {
    pub fn new() -> Self {
        Self {
            level: Dynamic::new(0.5),
        }
    }
}

/// Path A cells of the `Log` interface.
#[derive(Clone)]
pub struct Log {
    pub state: Dynamic<ReactiveEventLoggerState>,
    pub colors: Dynamic<LogColors>,
}

impl Log {
    pub fn new() -> Self {
        Self {
            state: Dynamic::new(ReactiveEventLoggerState::new()),
            colors: Dynamic::new(LogColors::default()),
        }
    }
}
